effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }


   /////////////////////////

    #define MAX_OFFSET maxoffset
    #define vertoffs false
    #define mirror true
    #define phase 0.0
    #define progress (1.57 * progressx)

     float rand(float co) { return fract(sin(co*(91.3458+deltax)) * 47453.5453); }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

        /////////////////////////

    	vec4 result;

    	//////////////////////////

    	vec2 uv = acScreenNorm;

        vec2 texel = 1. / acScreenNorm;
        texel *= rot2m(angle*0.0174533);
        texel += (0.0,progressb)*vec2(-1.,1.)/500.;

        vec4 img = texColor;

        // float step_y;
        // if( stepy ) { step_y = texel.y*(rand(uv.x)*100.0); }
        // else { step_y = texel.y*(rand(uv.x)*MAX_OFFSET) * (sin(sin(-1.57*0.5))*2.0+1.3); }

        float step_y = texel.y*(rand(uv.x)*MAX_OFFSET) * (sin(sin(-1.57*0.5))*2.0+1.3);
        step_y += rand(uv.x*uv.y*1.0)*pixel*sin(1.0);								// shake offset and modulate it
        step_y = mix(step_y, step_y*rand(uv.x*0.0)*0.5, sin(progress)); 					// more noisy spikes

        if ( dot(img,  vec4(0.299, 0.587, 0.114, 0.0) ) > 1.2*(sin(1.0)*0.325+0.50)){
        	uv.y+=step_y;
        } else{
        	uv.y-=step_y;
        }

        img = texture2DCv(inputImg.texture, uv);

        //////////////////////////

        result = mix(texColor,img,1.0) * texColor.a;
        if ( offside) { result = mix(texColor,img,1.0); }

        gl_FragColor = newLayer(texColor,result);

    }
